#!/usr/bin/env node
// P20-T13: Golden vor Produktcode; Guard auf jeder echten Test-DB-Abfrage.
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {readFile} from 'node:fs/promises';
import {oeffneGeschuetzteShellTestDb} from './lib/test-db-schutz.mjs';
const base=new URL(process.env.TEST_DATABASE_URL??process.env.DATABASE_URL??'');
assert.equal(base.pathname,'/synapse_test');assert.equal(base.port,'5433');
const schema='p20_r13_'+process.pid;
const db=await oeffneGeschuetzteShellTestDb();
await db.query('SET search_path TO '+schema+',public');
const mode=process.argv[2]??'test';
const req=createRequire(new URL('../packages/rest-api/package.json',import.meta.url));
const Fastify=req('fastify');
Object.assign(process.env,{OLLAMA_MODEL:'r13-fixture',SYNAPSE_OLLAMA_MODEL_DIGEST:'a'.repeat(64),
  SYNAPSE_OLLAMA_NATIVE_DIMENSION:'8',EMBEDDING_TARGET_DIM:'4',EMBEDDING_NUM_CTX:'512',
  SYNAPSE_GPU_REQUIRED_TOTAL_MB:'100',SYNAPSE_GPU_REQUIRED_FREE_MB:'50',
  EMBEDDING_QUERY_PREFIX:'q: ',EMBEDDING_DOC_PREFIX:'d: ',SYNAPSE_NODE_MAX_CLAIMS:'2',
  SYNAPSE_API_FEATURES:'compute_resources',OLLAMA_URL:'http://127.0.0.1:9'});
globalThis.fetch=async()=>{throw Error('Synthetische Probe ohne Netzwerk');};
const core=await import('../packages/core/dist/index.js');
const {createEmbeddingNodeRoutes}=await import('../packages/rest-api/dist/routes/embedding-nodes.js');
const tokens={gpu:{kind:'service',scope:'compute-node:r13-gpu',token_hash:'r13-gpu-hash'},
  cpu:{kind:'service',scope:'compute-node:r13-cpu',token_hash:'r13-cpu-hash'},
  admin:{kind:'session',scope:'mcp:tools',token_hash:'r13-admin-hash'}};
const app=Fastify();
await app.register(createEmbeddingNodeRoutes({db,validateToken:async x=>tokens[x]??null}));
const boot='11111111-1111-4111-8111-111111111111';
const fp={model:'r13-fixture',modelDigest:'a'.repeat(64),nativeDimension:8,targetDimension:4,numCtx:512};
const gpu={...fp,nodeId:'r13-gpu',host:'fixture',ollamaUrl:'http://127.0.0.1:9',
  vramTotalMb:1000,vramFreeMb:0,maxConcurrency:2,bootId:boot,bootStartedAt:'2026-01-01T00:00:00Z'};
const send=(method,path,body,token='gpu',version=false)=>app.inject({method,url:'/api/embedding-nodes/'+path,
  headers:{authorization:'Bearer '+token,...(version?{'x-synapse-contract-version':'1'}:{})},
  ...(body===undefined?{}:{payload:body})});
const stable=x=>Array.isArray(x)?x.map(stable):x&&typeof x==='object'?Object.fromEntries(
  Object.entries(x).map(([k,v])=>[k,['serverTime','server_now','boot_started_at','registriert_am','letzter_kontakt','aktualisiert_am','bis','seit'].includes(k)?'<zeit>':stable(v)])):x;
const snap={};
async function capture(name,method,path,body){const r=await send(method,path,body);snap[name]={status:r.statusCode,body:stable(r.json())};return r;}
let made=false;
try{
  await db.query('CREATE SCHEMA '+schema);made=true;
  await db.query('CREATE TABLE '+schema+'.embedding_knoten (LIKE public.embedding_knoten INCLUDING ALL)');
  await capture('reference','GET','reference');
  assert.equal((await capture('register','POST','register',gpu)).statusCode,201);
  await capture('self','GET','r13-gpu/self');
  await capture('heartbeat','POST','r13-gpu/heartbeat',{...fp,status:'ready',vramFreeMb:0,activeJobs:0,bootId:boot,sequence:1});
  core.pausiereWorker('gpu_knoten',{dauer_min:5,grund:'p20_r13',von:'sol-1'});
  await capture('claims','POST','r13-gpu/claims',{limit:1});
  await capture('complete','POST','r13-gpu/claims/complete',{});
  await capture('release','POST','r13-gpu/claims/release',{claims:[]});
  if(mode==='golden-capture')console.log(JSON.stringify({golden:snap}));
  else{
    const expected=JSON.parse(await readFile(new URL('./fixtures/p20-r13-legacy.golden.json',import.meta.url),'utf8'));
    assert.equal(JSON.stringify(snap),JSON.stringify(expected),'Legacy-Golden bytegleich');
    console.log('R1.3 sieben Legacy-Goldens unverändert');
    const {CPU_NODES_SCHEMA_SQL}=await import('../packages/core/dist/db/cpu-nodes-schema.js');
    await db.query(CPU_NODES_SCHEMA_SQL);await db.query(CPU_NODES_SCHEMA_SQL);
    process.env.SYNAPSE_COMPUTE_RESOURCE_BINDINGS=JSON.stringify({'r13-cpu':{hostResourceDomain:'r13-host',deviceIds:[],location:'unraid'}});
    const cpu={nodeId:'r13-cpu',host:'fixture',bootId:boot,bootStartedAt:'2026-01-01T00:00:00Z',maxConcurrency:2,
      contractVersion:1,features:['compute_cpu_only','compute_resources'],
      location:'unraid',hostResourceDomain:'r13-host',resources:{cpu:{},ram:{},gpus:[]},
      capabilities:[{id:'reverse.inspect',profileRef:{scope:'test',id:'cpu-profile',revision:'1',sha256:'c'.repeat(64)}}]};
    assert.equal((await send('POST','register',cpu,'cpu',true)).statusCode,503,'Gate aus');
    process.env.SYNAPSE_API_FEATURES='compute_resources,compute_cpu_only';
    assert.equal((await send('POST','register',cpu,'cpu',false)).statusCode,503,'A1 fehlt');
    const registered=await send('POST','register',cpu,'cpu',true);
    assert.equal(registered.statusCode,201,registered.body);
    const row=(await db.query('SELECT * FROM embedding_knoten WHERE node_id=$1',['r13-cpu'])).rows[0];
    for(const key of ['modell','modell_digest','ollama_url','native_dimension','ziel_dimension','num_ctx','vram_gesamt_mb','vram_frei_mb'])assert.equal(row[key],null,key);
    assert.equal(row.node_kind,'cpu');assert.equal(row.ressourcen.cpu.cores.value,null);
    assert.equal((await send('GET','r13-cpu/self',undefined,'cpu',false)).statusCode,404);
    assert.equal((await send('GET','r13-cpu/self',undefined,'cpu',true)).statusCode,200);
    assert.equal((await send('POST','r13-cpu/claims',{limit:1},'cpu',true)).statusCode,403,'Nie Embeddingclaim');
    assert.equal((await send('POST','r13-cpu/claims/complete',{},'cpu',true)).statusCode,403);
    const hb={contractVersion:1,features:cpu.features,status:'ready',activeJobs:0,bootId:boot,sequence:1,resources:cpu.resources};
    assert.equal((await send('POST','r13-cpu/heartbeat',hb,'cpu',true)).statusCode,200);
    assert.equal((await send('POST','r13-cpu/heartbeat',hb,'cpu',true)).statusCode,409);
    assert.equal((await send('POST','r13-cpu/heartbeat',{...hb,sequence:2,bootId:'22222222-2222-4222-8222-222222222222'},'cpu',true)).statusCode,409);
    assert.equal((await send('POST','register',{...cpu,model:'dummy'},'cpu',true)).statusCode,400);
    assert.equal((await send('POST','register',{...cpu,resources:{gpus:[{deviceId:'GPU-fake'}]}},'cpu',true)).statusCode,400);
    const oldList=await app.inject({method:'GET',url:'/api/embedding-nodes',headers:{authorization:'Bearer admin'}});
    assert.ok(oldList.json().nodes.every(n=>n.node_id!=='r13-cpu'));
    const modern=await app.inject({method:'GET',url:'/api/embedding-nodes',headers:{authorization:'Bearer admin','x-synapse-contract-version':'1'}});
    assert.ok(modern.json().nodes.some(n=>n.node_id==='r13-cpu'));
    await capture('reference','GET','reference');
    await capture('register','POST','register',gpu);
    await capture('self','GET','r13-gpu/self');
    await capture('heartbeat','POST','r13-gpu/heartbeat',{...fp,status:'ready',vramFreeMb:0,activeJobs:0,bootId:boot,sequence:1});
    await capture('claims','POST','r13-gpu/claims',{limit:1});
    await capture('complete','POST','r13-gpu/claims/complete',{});
    await capture('release','POST','r13-gpu/claims/release',{claims:[]});
    assert.equal(JSON.stringify(snap),JSON.stringify(expected),'Legacy-Golden mit CPU-Zeile bytegleich');
    console.log('R1.3 CPU/Gates/NULL/Heartbeatfences/Legacyfilter: grün');
  }
}finally{
  await app.close();await core.closePool();
  if(made)await db.query('DROP SCHEMA '+schema+' CASCADE');
  await db.end();
}

import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {readFileSync} from 'node:fs';
import {oeffneGeschuetzteShellTestDb} from './lib/test-db-schutz.mjs';
const raw = new URL(process.env.DATABASE_URL ?? '');
assert.equal(raw.port,'5433'); assert.equal(raw.pathname,'/synapse_test');
raw.searchParams.set('options','-c search_path=p20_r12,public');
const db=await oeffneGeschuetzteShellTestDb(raw.href);
const pool={query:db.query,connect:async()=>({query:db.query,release(){}})};
await db.query('CREATE SCHEMA IF NOT EXISTS p20_r12');
const mode=process.argv[2]??'verify';
const A='p20_t9_a', B='p20_t9_b', NODE='p20-r12-pc';
Object.assign(process.env,{SYNAPSE_COMPUTE_POLICY_ENABLED:'0',OLLAMA_MODEL:'p20-r12-model',
  SYNAPSE_OLLAMA_MODEL_DIGEST:'a'.repeat(64),SYNAPSE_OLLAMA_NATIVE_DIMENSION:'8',
  EMBEDDING_TARGET_DIM:'4',EMBEDDING_NUM_CTX:'512',SYNAPSE_GPU_REQUIRED_TOTAL_MB:'100',
  SYNAPSE_GPU_REQUIRED_FREE_MB:'50',EMBEDDING_QUERY_PREFIX:'q: ',EMBEDDING_DOC_PREFIX:'d: ',
  SYNAPSE_NODE_MAX_CLAIMS:'8',OLLAMA_URL:'http://127.0.0.1:9',SYNAPSE_API_FEATURES:'compute_resources'});
process.env.SYNAPSE_COMPUTE_RESOURCE_BINDINGS=JSON.stringify({[NODE]:{
  hostResourceDomain:'p20-fixture-pc',deviceIds:['GPU-p20-fixture'],location:'pc'}});
globalThis.fetch=async()=>{throw new Error('kein externes IO');};
const core=await import('../packages/core/dist/index.js');
const corePool=core.getPool();
corePool.query=db.query;
corePool.connect=pool.connect;
const claims=await import('../packages/core/dist/services/embedding-claims.js');
const tables=['projects','code_files','code_chunks','embed_prioritaet','auth_tokens','embedding_knoten','work_jobs','work_job_audit'];
const boot='11111111-1111-4111-8111-111111111111';
const authHash=[WERT];
async function seed(projects=[A]) {
  for(const p of projects) {
    await db.query("INSERT INTO projects(name,hostname,path,enabled) VALUES($1,'test',$2,true)",[p,'/fixture/'+p]);
    await db.query("INSERT INTO code_files(id,project,file_path,file_name,file_type) VALUES($1,$2,'src/a.ts','a.ts','ts')",[p+'-file',p]);
    await db.query("INSERT INTO embed_prioritaet(project,stufe,gesetzt_von) VALUES($1,1,'sol-5')",[p]);
    for(const [n,prio] of [[1,1],[2,null],[3,-1]]) await db.query(
      "INSERT INTO code_chunks(id,project,file_path,chunk_index,content,line_start,line_end,prio) VALUES($1,$2,'src/a.ts',$3,$4,1,1,$5)",
      [p+'-'+n,p,n,'fixture '+n,prio]);
  }
}
const reset=()=>db.query('UPDATE code_chunks SET claimed_by=NULL,claim_token=[WERT],lease_until=NULL,claim_attempt=0,embedded_at=NULL');
const claim=(node=NODE,options={})=>claims.claimEmbeddingChunks(node,{limit:8,maxConcurrent:100,...options},pool);
const normalized=cs=>cs.map(({claimToken,leaseUntil,...c})=>({...c,claimToken:'[WERT]',leaseUntil:'<zeit>'}));
let app;
try {
  for(const name of tables) await db.query('CREATE TABLE p20_r12.'+name+' (LIKE public.'+name+' INCLUDING DEFAULTS INCLUDING CONSTRAINTS)');
  await db.query('CREATE UNIQUE INDEX ON embedding_knoten(node_id)');
  await db.query('CREATE UNIQUE INDEX ON work_jobs(idempotency_key)');
  await db.query('CREATE UNIQUE INDEX ON code_chunks(id)');
  await seed();
  const old=normalized(await claim());
  assert.equal(old.length,3);
  if(mode==='record') console.log('GOLDEN='+JSON.stringify(old));
  else {
    assert.equal(JSON.stringify(old),JSON.stringify(JSON.parse(readFileSync(new URL('./fixtures/p20-r12-claims.golden.json',import.meta.url),'utf8'))));
    const policy=await import('../packages/core/dist/services/compute-policy.js');
    if(mode==='red') assert.equal(typeof policy.pruefeComputeZuteilung,'function');
    else {
      const {COMPUTE_POLICY_SCHEMA_SQL}=await import('../packages/core/dist/db/compute-policy-schema.js');
      await db.query(COMPUTE_POLICY_SCHEMA_SQL);await db.query(COMPUTE_POLICY_SCHEMA_SQL);
      await db.query("INSERT INTO auth_tokens(token_hash,kind,scope) VALUES($1,'service',$2)",[authHash,'compute-node:'+NODE]);
      // Policy darf vor Registry bestehen, erzeugt aber keine gesunde Knoten-Zeile.
      const pre=await policy.setzeComputePolicy(NODE,{ausfuehrungsfreigabe:true},db);
      assert.equal(pre.policyRevision,'1');
      assert.equal((await db.query('SELECT COUNT(*) AS n FROM embedding_knoten')).rows[0].n,'0');
      const ref={model:process.env.OLLAMA_MODEL,modelDigest:'a'.repeat(64),nativeDimension:8,targetDimension:4,numCtx:512};
      const {registerEmbeddingNode}=await import('../packages/rest-api/dist/services/embedding-nodes.js');
      await registerEmbeddingNode(authHash,{...ref,nodeId:NODE,host:'fixture',ollamaUrl:'http://127.0.0.1:9',
        vramTotalMb:1000,vramFreeMb:0,maxConcurrency:8,bootId:boot,bootStartedAt:'2026-01-01T00:00:00Z'},db);
      process.env.SYNAPSE_COMPUTE_POLICY_ENABLED='1';
      await reset();assert.equal((await claim()).length,3,'Standardprojekt an nach Consent');
      await reset();await policy.setzeComputeProjektPolicy(A,{pc_gpu_ausgeschlossen:true},db);
      assert.equal((await claim()).length,0,'Opt-out in allen drei Priozweigen');
      await seed([B]); // zwei eigene Testprojekte, A bleibt gesperrt
      assert.ok((await claim()).every(c=>c.project===B),'Normale Auswahl überspringt gesperrtes Projekt');
      await reset();const held=await claim();assert.equal(held.length,3);
      await policy.setzeComputeProjektPolicy(B,{pc_gpu_ausgeschlossen:true},db);
      assert.equal((await claim()).length,0);
      assert.equal((await db.query('SELECT COUNT(*) AS n FROM code_chunks WHERE claimed_by=$1 AND lease_until>NOW()',[NODE])).rows[0].n,'3','laufende Leases bleiben');
      // Regulärer Abschluss weiterhin zulässig nach Opt-out, ohne neue Zuteilung.
      const done=await claims.completeEmbeddingClaim({nodeId:NODE,chunkId:held[0].chunkId,claimToken:held[0].claimToken,
        contentHash:held[0].contentHash,vector:[1,0,0,0],expectedDimension:4},
        {pool,ensureCollection:async()=> 'p20_t9',writeVector:async()=>{}});
      assert.equal(done.completed,true);
      await reset();assert.equal((await claim('p20-r12-server',{internalServer:true})).length,6,'Unraid übernimmt Opt-out');
      await reset();await policy.setzeComputeProjektPolicy(A,{pc_gpu_ausgeschlossen:false},db);
      await policy.setzeComputePolicy(NODE,{usersperre:{embedding:true}},db);
      const decision=await policy.pruefeComputeZuteilung({nodeId:NODE,project:A,capability:'embedding',
        profileCompatible:true,resourcesAvailable:true},db);
      assert.equal(decision.allowed,false);assert.equal(decision.reason,'Fähigkeit vom Nutzer gesperrt');
      assert.equal((await claim()).length,0,'Usersperre gewinnt gegen Automatik');
      await policy.setzeComputePolicy(NODE,{modus:'automatik'},db);
      assert.equal((await claim()).length,0,'Modus/Empfehlung hebt Usersperre nicht auf');
      await policy.setzeComputePolicy(NODE,{usersperre:{embedding:false},modus:'manuell',faehigkeit_schalter:{embedding:false}},db);
      assert.equal((await claim()).length,0,'Manuelles Häkchen erforderlich');
      const active=await policy.setzeComputePolicy(NODE,{faehigkeit_schalter:{embedding:true}},db);
      assert.ok(BigInt(active.policyRevision)>1n);assert.equal((await claim()).length,3);
      await reset();await policy.setzeComputePolicy(NODE,{ausfuehrungsfreigabe:false},db);
      assert.equal((await claim()).length,0,'Trayfreigabe aus verhindert PC-Arbeit');
      assert.equal((await claim('p20-r12-server',{internalServer:true})).length,6);
      await reset();
      const req=createRequire(new URL('../packages/rest-api/package.json',import.meta.url));
      const {registerComputePolicyRoutes}=await import('../packages/rest-api/dist/routes/compute-policy.js');
      app=req('fastify')();
      const identities={compute:{kind:'service',scope:'compute-node:'+NODE,token_hash:authHash},
        daemon:{kind:'service',scope:'daemon:p20-fixture',token_hash:'[WERT]'},
        session:{kind:'session',scope:null,token_hash:'[WERT]'}};
      await registerComputePolicyRoutes(app,{db,validateToken:async t=>identities[t]??null});
      const request=(method,path,payload,t='compute')=>app.inject({method,url:path,headers:{authorization:'[WERT]'+t},
        ...(payload?{payload}:{})});
      assert.equal((await request('PATCH','/api/embedding-nodes/'+NODE+'/policy',{ausfuehrungsfreigabe:true})).statusCode,403);
      assert.equal((await request('PATCH','/api/projects/'+A+'/compute-policy',{pc_gpu_ausgeschlossen:true})).statusCode,403);
      assert.equal((await request('PATCH','/api/embedding-nodes/'+NODE+'/policy',{ausfuehrungsfreigabe:true},'daemon')).statusCode,200);
      const self=await request('GET','/api/embedding-nodes/'+NODE+'/policy');
      assert.equal(self.statusCode,200);assert.ok(self.json().recommendations.embedding.grund);
      assert.ok(self.json().recommendations.embedding.zeit);
      assert.equal((await request('GET','/api/embedding-nodes/fremd/policy')).statusCode,403);
      assert.equal((await request('PATCH','/api/embedding-nodes/'+NODE+'/policy',{lan_bevorzugen:true},'daemon')).statusCode,400);
      assert.equal((await request('PATCH','/api/projects/'+A+'/compute-policy',{pc_gpu_ausgeschlossen:true},'session')).statusCode,200);
      assert.equal((await request('GET','/api/projects/'+A+'/compute-policy',null,'session')).json().policy.pc_gpu_ausgeschlossen,true);
      console.log('R1.2/T9 grün: Legacybytegolden, Vorregistry, Consent/Usersperren/Manuell, Projektoptout3Zweige+Unraid, regulärer Abschluss, API-Autorisierung/Revision/Empfehlung');
    }
  }
} finally {
  await app?.close();
  for(const name of ['compute_node_policy','compute_project_policy',...tables].reverse()) await db.query('DROP TABLE IF EXISTS p20_r12.'+name);
  await db.end();await core.closePool();
}

/** RV9: Kernel/Rechte/Status und Alt-Schemas, nur synthetisches p18_rv9 in synapse_test:5433. */
import assert from 'node:assert/strict';
import {createHash,randomUUID} from 'node:crypto';
import {createRequire} from 'node:module';
const url=new URL(process.env.DATABASE_URL||'http://invalid');
assert.equal(url.port,'5433');assert.equal(url.pathname,'/synapse_test');
delete process.env.SYNAPSE_DATABASE_URL;
const schema='p18_rv9_'+process.pid;
url.searchParams.set('options','-c search_path='+schema+',public');
process.env.DATABASE_URL=url.toString();
process.env.SYNAPSE_SKIP_EMBEDDINGS='1';process.env.QDRANT_URL='http://127.0.0.1:1';
const core=await import('../dist/index.js');
assert.equal(typeof core.fuehreReverseAus,'function','RV9 Dispatcher fehlt (rote Kontrolle)');
const {REVERSE_DEFINITION,createReverseToolService,REVERSE_FEHLERCODES}=core;
const {REVERSE_SCHEMA_SQL}=await import('../dist/db/reverse-schema.js');
const pool=core.getPool(),project='p18_rv9',agent='p18_rv9-agent',other='p18_rv9-other',rid='rev-fixture-000001',second='rev-fixture-000002';
const hash=v=>createHash('sha256').update(JSON.stringify(v)).digest('hex');
const required=['reverse_id','datei','format','arch','bits','schicht','schicht_angefragt','status','fehlercode','werkzeug','merkmale','fortschritt','container'];
let sequence=0;
const service=createReverseToolService({pool});
const call=(action,extra={},who=agent)=>service.ausfuehren({action,agent_id:who,project,reverse_id:rid,...extra});
const check=r=>{for(const key of required)assert(Object.hasOwn(r,key),'Pflichtfeld '+key);for(const key of required)assert(Object.hasOwn(r.felder,key),'Hinweisfeld '+key);return r;};
try {
 await pool.query('CREATE SCHEMA '+schema);
 for(const table of ['agent_sessions','projects','tool_aktivitaet'])await pool.query('CREATE TABLE '+schema+'.'+table+' (LIKE public.'+table+' INCLUDING DEFAULTS INCLUDING INDEXES)');
 await pool.query(REVERSE_SCHEMA_SQL);
 await pool.query("INSERT INTO agent_sessions(id,project,status,sitzung_seit) VALUES($1,$3,'active',NOW()),($2,$3,'active',NOW()),('koordinator',$3,'active',NOW())",[agent,other,project]);
 await pool.query("INSERT INTO projects(name,hostname,path,enabled) VALUES($1,'fixture','/synthetic/p18_rv9',true)",[project]);
 await pool.query("INSERT INTO reverse_eintraege(id,titel,tags) VALUES($1,'Fixture A',ARRAY['demo']),($2,'Fixture B',ARRAY['andere'])",[rid,second]);
 await pool.query("INSERT INTO reverse_medien(id,eintrag_id,position,bezeichnung,art,satz_sha256) VALUES(1,$1,0,'CD1','iso',$2),(2,$1,1,'CD2','iso',$3),(3,$4,0,'DVD','iso',$5)",[rid,'a'.repeat(64),'b'.repeat(64),second,'c'.repeat(64)]);
 const list=check(await call('liste',{reverse_id:undefined,limit:1}));
 assert.equal(list.total,2);assert.equal(list.gekappt,true);assert.equal(list.naechster_offset,1);
 assert.equal(list.eintraege.length,1);assert(!JSON.stringify(list).includes('storage_key'));
 assert.equal((await call('liste',{tag:'demo'})).total,1);assert.equal((await call('liste',{query:"' OR 1=1 --"})).total,0,'Suche gebunden');
 assert.equal((await call('vorschlaege')).total,2);
 const entry=check(await call('eintrag'));assert.equal(entry.eintrag.medien.length,2);
 assert.equal((await call('archivieren')).fehlercode,'keine_berechtigung');
 assert.equal((await call('bestaetigen')).fehlercode,'keine_berechtigung');
 const confirm=await call('bestaetigen',{titel:'Titel neu',medien:[{id:'2',bezeichnung:'DiscB'},{id:'1',bezeichnung:'DiscA'}]},'koordinator');
 assert.equal(confirm.success,true);assert.equal(confirm.eintrag.status,'bestaetigt');assert.equal(confirm.eintrag.medien[0].id,'2');
 assert.equal((await call('bestaetigen',{},'koordinator')).success,true,'Bestätigung idempotent');
 await pool.query("INSERT INTO reverse_dateien(id,eintrag_id,medium_id,pfad,format,arch,bits,art,status,metadaten) VALUES(1,$1,1,'cd1/game.exe','pe','x86',32,'binaer','offen','{\"merkmale\":[\"debug_symbole\"]}')",[rid]);
 assert.equal(check(await call('status',{datei:'cd1/game.exe'})).fehlercode,'nicht_gebunden');
 assert.equal((await call('analysieren',{datei:'cd1/game.exe',bis_schicht:'S3'})).fehlercode,'nicht_gebunden');
 assert.equal((await call('binden',{project:'fremd'})).fehlercode,'keine_berechtigung','Agent darf fremdes Projekt nicht behaupten');
 const bindings=await Promise.all(Array.from({length:4},()=>call('binden')));
